import{b as a,O as r,g as e,j as l}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"课程总结","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/summary/index.md","filePath":"数据库管理/MySQL必知必会/5.课程总结.md","lastUpdated":1782140566000}'),o={name:"database/mysql/summary/index.md"};function i(n,t,s,d,h,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h1><blockquote><p>20 篇文章走完，你学到了什么？接下来往哪走？</p></blockquote><h2 id="你学会了什么" tabindex="-1">你学会了什么 <a class="header-anchor" href="#你学会了什么" aria-label="Permalink to &quot;你学会了什么&quot;">​</a></h2><p>从一行 <code>SELECT name FROM users</code> 开始，一路走到了事务处理、存储过程、安全管理。回头看看你走过的路：</p><table tabindex="0"><thead><tr><th>模块</th><th>掌握的核心技能</th></tr></thead><tbody><tr><td>开篇</td><td>MySQL 是什么、怎么装、命令行基本操作</td></tr><tr><td>数据查询（10 篇）</td><td>SELECT、WHERE、ORDER BY、函数、聚合、GROUP BY、子查询、JOIN、UNION、全文本搜索</td></tr><tr><td>数据操作（3 篇）</td><td>INSERT、UPDATE、DELETE、建表、改表、约束</td></tr><tr><td>进阶必学（5 篇）</td><td>视图、事务、存储过程、安全管理、维护与性能优化</td></tr></tbody></table><h2 id="你已经能做什么" tabindex="-1">你已经能做什么 <a class="header-anchor" href="#你已经能做什么" aria-label="Permalink to &quot;你已经能做什么&quot;">​</a></h2><ul><li>独立完成单表查询和多表联结查询</li><li>写出带条件筛选、排序、分组的统计 SQL</li><li>用子查询解决&quot;查询里套查询&quot;的需求</li><li>用 JOIN 把分散在多张表的数据拼成完整视图</li><li>创建和管理表结构，控制数据约束</li><li>用事务保证数据一致性（转账不丢钱）</li><li>给不同用户分配合适的数据库权限</li><li>用 EXPLAIN 分析查询性能，加索引优化</li></ul><p>基本上，日常开发中 90% 的数据库操作你都覆盖到了。</p><h2 id="还没讲到但值得了解的" tabindex="-1">还没讲到但值得了解的 <a class="header-anchor" href="#还没讲到但值得了解的" aria-label="Permalink to &quot;还没讲到但值得了解的&quot;">​</a></h2><ul><li><strong>主从复制与读写分离</strong> — 生产环境必备的高可用方案</li><li><strong>分库分表</strong> — 数据量过亿时的拆分策略</li><li><strong>SQL 执行原理</strong> — B+ 树索引、查询优化器内部机制</li><li><strong>JSON 数据类型</strong> — MySQL 8.0 的文档存储能力</li><li><strong>窗口函数</strong> — 比 GROUP BY 更灵活的分析函数</li><li><strong>Elasticsearch</strong> — 专业的中文搜索引擎</li></ul><blockquote><p>💡 上面这些不是入门阶段要啃的东西，但可以作为下一步的探索方向。</p></blockquote><h2 id="最重要的三句话" tabindex="-1">最重要的三句话 <a class="header-anchor" href="#最重要的三句话" aria-label="Permalink to &quot;最重要的三句话&quot;">​</a></h2><p>把整份教程浓缩成三句，记住它们就够了：</p><ol><li><strong>先 SELECT 确认，再动手改</strong> — 增删改之前多花 3 秒看一眼，比花 3 小时恢复强一万倍</li><li><strong>索引不是越多越好</strong> — 跑起来发现慢了，用 EXPLAIN 定位瓶颈，对症下药</li><li><strong>动手比看懂重要十倍</strong> — 每篇的小练习都亲手敲一遍，肌肉记忆比眼睛记忆靠谱得多</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li><strong>把练习跑完</strong> — 20 篇的自主练习都动手敲过一遍，才算真正学完</li><li><strong>搭一个自己的小项目</strong> — 博客、记账本、图书管理系统，找个感兴趣的用 MySQL 做存储</li><li><strong>读官方文档</strong> — <a href="https://dev.mysql.com/doc/refman/8.0/en/" target="_blank" rel="noreferrer">MySQL 8.0 Reference Manual</a> 是最终的权威参考</li></ol><p>教程有终点，学习没有。写 SQL 的路上遇到问题就查，跑多了自然熟了。</p>',17)])])}const _=a(o,[["render",i]]);export{g as __pageData,_ as default};
